    const numbers = [];
    const numRegex = /(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/gi;
    let m;
    while ((m = numRegex.exec(text)) !== null) {
      let val = parseFloat(m[1]);
      const unit = (m[2] || '').toLowerCase();
      if (unit.startsWith('k')) val *= 1000;
      else if (unit.startsWith('l')) val *= 100000;
      else if (unit.startsWith('m')) val *= 1000000;
      numbers.push(val);
    }
    income = numbers.find(n => n > 1000) || 600000;
  }

  if (income > 0 && income < 100000) {
    income = income * 12;
  }

  const net_new = Math.max(0, income - 75000);
  let tax_new = 0;
  if (net_new > 700000) {
    let temp = net_new;
    if (temp > 1500000) { tax_new += (temp - 1500000) * 0.3; temp = 1500000; }
    if (temp > 1200000) { tax_new += (temp - 1200000) * 0.2; temp = 1200000; }
    if (temp > 900000)  { tax_new += (temp - 900000) * 0.15; temp = 900000; }
    if (temp > 600000)  { tax_new += (temp - 600000) * 0.1; temp = 600000; }
    if (temp > 300000)  { tax_new += (temp - 300000) * 0.05; temp = 300000; }
  }

  const deductions_old = 50000 + 150000 + 25000;
  const net_old = Math.max(0, income - deductions_old);
  let tax_old = 0;
  if (net_old > 500000) {
    let temp = net_old;
    if (temp > 1000000) { tax_old += (temp - 1000000) * 0.3; temp = 1000000; }
    if (temp > 500000)  { tax_old += (temp - 500000) * 0.2; temp = 500000; }
    if (temp > 250000)  { tax_old += (temp - 250000) * 0.05; temp = 250000; }
  }

  const diff = Math.abs(tax_new - tax_old);
  const recommended = tax_new < tax_old ? 'New Regime' : 'Old Regime';

  return JSON.stringify({
    annual_income: income,
    standard_deduction: income > 75000 ? 75000 : income,
    taxable_income_new: net_new,
    taxable_income_old: net_old,
