(() => {
  let raw = $json.output || '';

  // 1. Try standard cleaning and parsing
  try {
    const cleaned = raw.replace(/```json|```/g, '').trim();
    return JSON.parse(cleaned);
  } catch (e) {}

  // 2. Try extracting JSON block between first { and last }
  try {
    const firstBrace = raw.indexOf('{');
    const lastBrace = raw.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
      const jsonStr = raw.substring(firstBrace, lastBrace + 1);
      return JSON.parse(jsonStr);
    }
  } catch (e) {}

  // 3. Fallback: Parse using Regex if JSON is completely malformed or has text wrappers
  try {
    let summary = "";
    let recommendations = [];
    let risks = [];
    let action_plan = [];

    // Extract summary
    const summaryMatch = raw.match(/"summary"\s*:\s*"([\s\S]*?)"/i) || raw.match(/summary:\s*([^\n]+)/i);
    if (summaryMatch) {
      summary = summaryMatch[1].trim();
    } else {
      const paragraphMatch = raw.match(/^([^\n]+)/);
      summary = paragraphMatch ? paragraphMatch[1].trim() : raw.substring(0, 200);
    }

    // Helper to extract list items from a section match
    const extractList = (sectionText) => {
      const doubleQuoted = sectionText.match(/"([^"]+)"/g);
      if (doubleQuoted && doubleQuoted.length > 0) {
        return doubleQuoted.map(i => i.replace(/^"|"$/g, '').trim());
      }
      return sectionText
        .split(/[\n,;]/)
        .map(l => l.replace(/^[-*\d.\s]+/, '').trim())
        .filter(l => l.length > 3 && !l.includes('[') && !l.includes(']'));
    };

    // Extract recommendations
    const recsMatch = raw.match(/"recommendations"\s*:\s*\[([\s\S]*?)\]/i) || raw.match(/recommendations:\s*([\s\S]*?)(?:risks|action_plan|summary|$)/i);
    if (recsMatch) {
      recommendations = extractList(recsMatch[1]);
    }

    // Extract risks
    const risksMatch = raw.match(/"risks"\s*:\s*\[([\s\S]*?)\]/i) || raw.match(/risks:\s*([\s\S]*?)(?:action_plan|recommendations|summary|$)/i);
    if (risksMatch) {
      risks = extractList(risksMatch[1]);
    }

    // Extract action plan
    const planMatch = raw.match(/"action_plan"\s*:\s*\[([\s\S]*?)\]/i) || raw.match(/action_plan:\s*([\s\S]*?)(?:risks|recommendations|summary|$)/i);
    if (planMatch) {
      action_plan = extractList(planMatch[1]);
    }

    if (recommendations.length === 0) recommendations = ["Please review your financial goals and adjust savings."];
    if (risks.length === 0) risks = ["Market volatility or lack of specific detailed financial inputs."];
    if (action_plan.length === 0) action_plan = ["Analyze monthly expenses", "Setup automated savings"];

    return {
      summary: summary.replace(/\\"/g, '"').replace(/\n/g, ' '),
      recommendations: recommendations,
      risks: risks,
      action_plan: action_plan
    };
  } catch (e) {
    return {
      summary: raw.substring(0, 500) + "...",
      recommendations: ["Review savings and investments monthly."],
      risks: ["Automatic parsing failed. Review raw response."],
      action_plan: ["Re-submit query with standard format."]
    };
  }
})()
}
